package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.codec.binary.Base64.encodeBase64String
 */
public class Base64_encodeBase64String_TriageGen0Test {

    @Test
    public void testEncodeBase64String_WithStandardData() {
        // Test with standard ASCII string "Hello"
        // "Hello" in Base64 is "SGVsbG8="
        byte[] input = "Hello".getBytes();
        String expected = "SGVsbG8=";
        String actual = Base64.encodeBase64String(input);
        assertEquals("The Base64 encoding for 'Hello' should match", expected, actual);
    }

    @Test
    public void testEncodeBase64String_WithEmptyArray() {
        // Test with an empty byte array
        byte[] input = new byte[0];
        String expected = "";
        String actual = Base64.encodeBase64String(input);
        assertEquals("Encoding an empty array should return an empty string", expected, actual);
    }

    @Test
    public void testEncodeBase64String_WithNull() {
        // Testing behavior with null input. 
        // Depending on the implementation of encodeBase64, this may throw a NullPointerException.
        try {
            Base64.encodeBase64String(null);
        } catch (NullPointerException e) {
            // Expected behavior for most standard library implementations when passing null to byte processing
        }
    }

    @Test
    public void testEncodeBase64String_WithSpecialCharacters() {
        // Test with non-ASCII/special characters to ensure UTF-8 handling
        // Using bytes that represent specific values
        byte[] input = new byte[]{(byte) 0xFF, (byte) 0x00, (byte) 0x7F};
        // Expected Base64 for [255, 0, 127] is "/wD/"
        String expected = "/wD/";
        String actual = Base64.encodeBase64String(input);
        assertEquals("The Base64 encoding for special bytes should match", expected, actual);
    }

    @Test
    public void testEncodeBase64String_WithLargeData() {
        // Test with a larger byte array to ensure no buffer issues
        byte[] input = new byte[1024];
        for (int i = 0; i < input.length; i++) {
            input[i] = (byte) (i % 256);
        }
        String actual = Base64.encodeBase64String(input);
        assertNotNull("Result should not be null", actual);
        assertFalse("Result should not be empty", actual.isEmpty());

        // Verify round-trip to ensure integrity
        byte[] decoded = Base64.decodeBase64(actual);
        assertArrayEquals("The decoded bytes should match the original input", input, decoded);
    }
}
